class AuthService { static Map<String, dynamic>? currentUser; static bool get isManager => currentUser?['role'] == 'Owner' || currentUser?['role'] == 'Manager' || currentUser?['role'] == 'SuperAdmin'; static bool get isSuperAdmin => currentUser?['role'] == 'SuperAdmin'; static String get name => currentUser?['name']?? 'Guest'; static String get shopId => currentUser?['shop_id']?? 'DEMO-SHOP-001'; static void logout() => currentUser = null; }
